    /// Corresponding beginning:
    /// <see cref="Patware.Diagnostics.ApplicationEvents.DependencyEvents.Resolving">115 — Dependency_Resolving</see>.
    /// </para>
    /// <para>Status: Stable. Introduced: 0.0.10.</para>
