    }

    /// <summary>
    /// Reports an external operation attempt that failed to complete within its timeout budget.
    /// </summary>
    /// <param name="externalName">The logical name of the external dependency, without credentials or request-specific data.</param>
    /// <param name="operationName">The logical name of the operation that timed out.</param>
    /// <param name="operationId">The identifier of this individual operation attempt. Use a different identifier for each retry.</param>
    /// <param name="timeoutMilliseconds">The configured timeout budget for this attempt, in milliseconds, rather than its measured elapsed duration.</param>
    /// <param name="exception">The original exception associated with the confirmed timeout.</param>
    /// <remarks>
    /// <para>Emit when the caller establishes that an external operation attempt timed out.</para>
    /// <para>An operation can time out while establishing a connection or while awaiting the result of an already connected operation.</para>
    /// <para>Cancellation alone does not establish a timeout. Do not emit this event for user cancellation or application shutdown.</para>
    /// <para>An OperationCanceledException is appropriate when the caller has established that the operation&apos;s timeout caused cancellation.</para>
    /// <para>The exception is required even when Error logging is disabled. Pass the original exception through the logging exception channel rather than converting it to a message-template property.</para>
    /// <para>Emit once per failed attempt at the boundary responsible for reporting the dependency operation. Avoid logging the same timeout again at each layer.</para>
    /// <para>OperationId identifies an individual attempt. A higher-level scope or trace can correlate several attempts belonging to the same logical operation.</para>
    /// <para>TimeoutMilliseconds describes the configured budget, not measured elapsed time. Cancellation observation and cleanup can occur after that budget expires.</para>
    /// <para>A timeout establishes that the caller did not obtain a result within its budget. It does not establish that the remote operation stopped or that it produced no side effects.</para>
    /// <para>This event reports a failed operation attempt. It does not establish that the dependency is permanently unavailable or that administrator intervention is immediately required.</para>
    /// <para>Emit Application_InDegradedMode separately only when application functionality becomes reduced. Emit Application_InNormalMode only when the application subsequently recovers from that degradation.</para>
    /// <para>Calling this method only emits a diagnostic record. It does not cancel operations, retry requests, manage a circuit breaker, or change application state.</para>
    /// <para>
    /// Relationships describe expected progression for the same application
    /// instance. Unrelated records may occur between related events.
    /// Missing records do not by themselves prove a failed transition.
    /// </para>
    /// <para>
    /// Beginning associated with this failure:
    /// <see cref="Patware.Diagnostics.ApplicationEvents.ExternalEvents.Connecting">201 — External_Connecting</see>.
    /// </para>
    /// <para>
    /// Beginning associated with this failure:
    /// <see cref="Patware.Diagnostics.ApplicationEvents.ExternalEvents.Calling">203 — External_Calling</see>.
    /// </para>
    /// <para>Status: Stable. Introduced: 0.0.5.</para>
    /// </remarks>
    /// <exception cref="InvalidOperationException">
    /// This group was default-initialized rather than obtained through
    /// a logger's category property.
    /// </exception>
    /// <exception cref="ArgumentNullException">
    /// The exception argument is null.
    /// </exception>
    public void OperationTimedOut(string @externalName, string @operationName, string @operationId, double @timeoutMilliseconds, Exception @exception)
    {
        ArgumentNullException.ThrowIfNull(@exception, nameof(@exception));
        ExternalEventMessages.OperationTimedOut(Logger, @externalName, @operationName, @operationId, @timeoutMilliseconds, @exception);
    }

    /// <summary>
    /// Reports that an external dependency could not serve an operation because of an observed availability failure.
    /// </summary>
    /// <param name="externalName">The logical name of the dependency, without credentials or request-specific data.</param>
    /// <param name="operationName">The logical name of the operation the dependency could not serve.</param>
    /// <param name="operationId">The identifier of this individual operation attempt. Use a different identifier for each retry.</param>
    /// <param name="reasonCode">An application-defined classification of the observed availability failure, such as ServiceUnavailable. Do not include response bodies or exception messages.</param>
    /// <param name="exception">The original exception associated with the availability failure, or null when the dependency returned an unavailable result without throwing.</param>
    /// <remarks>
    /// <para>Emit when the caller receives an explicit unavailable result or establishes that a dependency exception represents an availability failure.</para>
    /// <para>This event describes availability from the caller&apos;s perspective for one operation attempt. It does not establish that the service is unavailable to every caller.</para>
    /// <para>Use OperationTimedOut for an operation that exceeded its timeout budget. Do not emit both events merely to describe the same timeout.</para>
    /// <para>Do not classify every unsuccessful response or exception as service unavailability. Authentication, authorization, invalid requests, and business rejections have different meanings.</para>
    /// <para>A locally open circuit breaker does not establish the dependency&apos;s current availability because the operation was not attempted.</para>
    /// <para>ReasonCode is an application-defined classification suitable for grouping and alerting. Use a small documented set of values rather than request-specific text.</para>
    /// <para>Pass the original exception when one exists. Pass null for an unavailable result returned without an exception; do not manufacture an exception solely for logging.</para>
    /// <para>The exception travels through the logging exception channel and is not a message-template property.</para>
    /// <para>Emit once per failed attempt at the boundary responsible for reporting the dependency operation. Use a higher-level scope or trace to correlate retries.</para>
    /// <para>A failed attempt does not automatically change application mode. Emit Application_InDegradedMode separately when functionality becomes reduced and Application_InNormalMode after recovery.</para>
    /// <para>User cancellation and application shutdown are not availability failures.</para>
    /// <para>Calling this method only emits a diagnostic record. It does not retry requests, operate a circuit breaker, or change application state.</para>
    /// <para>
    /// Relationships describe expected progression for the same application
    /// instance. Unrelated records may occur between related events.
    /// Missing records do not by themselves prove a failed transition.
    /// </para>
    /// <para>
    /// Beginning associated with this failure:
    /// <see cref="Patware.Diagnostics.ApplicationEvents.ExternalEvents.Connecting">201 — External_Connecting</see>.
    /// </para>
    /// <para>
    /// Beginning associated with this failure:
    /// <see cref="Patware.Diagnostics.ApplicationEvents.ExternalEvents.Calling">203 — External_Calling</see>.
    /// </para>
    /// <para>Status: Stable. Introduced: 0.0.6.</para>
    /// </remarks>
    /// <exception cref="InvalidOperationException">
    /// This group was default-initialized rather than obtained through
    /// a logger's category property.
    /// </exception>
    public void ServiceUnavailable(string @externalName, string @operationName, string @operationId, string @reasonCode, Exception? @exception)
    {
        ExternalEventMessages.ServiceUnavailable(Logger, @externalName, @operationName, @operationId, @reasonCode, @exception);
    }

}

/// <summary>
/// Implements External event emission using generated logging methods.
/// </summary>
/// <remarks>
/// Keeping these methods internal prevents implementation details from
/// appearing in the public logger API. Microsoft supplies their bodies
/// through logging source generation.
/// </remarks>
internal static partial class ExternalEventMessages
{
    [LoggerMessage(
        EventId = 201,
        EventName = "External_Connecting",
        Level = LogLevel.Information,
        Message = "Connecting to external dependency {ExternalName}. Operation: {OperationName}. Attempt: {OperationId}.")]
    internal static partial void Connecting(
        ILogger logger, string ExternalName, string OperationName, string OperationId);

    [LoggerMessage(
        EventId = 202,
        EventName = "External_Connected",
        Level = LogLevel.Information,
        Message = "Connected to external dependency {ExternalName}. Operation: {OperationName}. Attempt: {OperationId}.")]
    internal static partial void Connected(
        ILogger logger, string ExternalName, string OperationName, string OperationId);

    [LoggerMessage(
        EventId = 203,
        EventName = "External_Calling",
        Level = LogLevel.Information,
        Message = "Calling external dependency {ExternalName}. Operation: {OperationName}. Attempt: {OperationId}.")]
    internal static partial void Calling(
        ILogger logger, string ExternalName, string OperationName, string OperationId);

    [LoggerMessage(
        EventId = 214,
        EventName = "External_CallCompleted",
        Level = LogLevel.Information,
        Message = "External dependency {ExternalName} operation completed. Operation: {OperationName}. Attempt: {OperationId}.")]
    internal static partial void CallCompleted(
        ILogger logger, string ExternalName, string OperationName, string OperationId);

    [LoggerMessage(
        EventId = 502,
        EventName = "External_AuthenticationFailed",
        Level = LogLevel.Warning,
        Message = "External authentication failed. Dependency: {ExternalName}. Operation: {OperationName}. Attempt: {OperationId}. Reason: {ReasonCode}.")]
    internal static partial void AuthenticationFailed(
        ILogger logger, string ExternalName, string OperationName, string OperationId, string ReasonCode, Exception? Exception);

    [LoggerMessage(
        EventId = 503,
        EventName = "External_AuthorizationFailed",
        Level = LogLevel.Warning,
        Message = "External authorization failed. Dependency: {ExternalName}. Operation: {OperationName}. Attempt: {OperationId}. Reason: {ReasonCode}.")]
    internal static partial void AuthorizationFailed(
        ILogger logger, string ExternalName, string OperationName, string OperationId, string ReasonCode, Exception? Exception);

    [LoggerMessage(
        EventId = 601,
        EventName = "External_OperationTimedOut",
        Level = LogLevel.Error,
        Message = "External operation timed out. Dependency: {ExternalName}. Operation: {OperationName}. Attempt: {OperationId}. Timeout: {TimeoutMilliseconds} milliseconds.")]
    internal static partial void OperationTimedOut(
        ILogger logger, string ExternalName, string OperationName, string OperationId, double TimeoutMilliseconds, Exception Exception);

    [LoggerMessage(
        EventId = 602,
        EventName = "External_ServiceUnavailable",
        Level = LogLevel.Error,
        Message = "External service unavailable. Dependency: {ExternalName}. Operation: {OperationName}. Attempt: {OperationId}. Reason: {ReasonCode}.")]
    internal static partial void ServiceUnavailable(
        ILogger logger, string ExternalName, string OperationName, string OperationId, string ReasonCode, Exception? Exception);

}
